cd /workspace && python3 -c "
import sqlite3, json

conn = sqlite3.connect('world.db')
conn.row_factory = sqlite3.Row

# Look for order ORD-E0E671
rows = conn.execute(\"SELECT * FROM orders WHERE order_id='ORD-E0E671'\").fetchall()
if rows:
    for r in rows:
        print('=== ORDER ===')
        for k in r.keys():
            print(f'  {k}: {r[k]}')
else:
    print('Order ORD-E0E671 not found')

# Look for order items
print()
items = conn.execute(\"SELECT * FROM order_items WHERE order_id='ORD-E0E671'\").fetchall()
if items:
    for item in items:
        print('=== ORDER ITEM ===')
        for k in item.keys():
            print(f'  {k}: {item[k]}')
else:
    print('No order items found for ORD-E0E671')

# Look for Aurora product
print()
products = conn.execute(\"SELECT * FROM products WHERE name LIKE '%Aurora%'\").fetchall()
if products:
    for p in products:
        print('=== PRODUCT ===')
        for k in p.keys():
            print(f'  {k}: {p[k]}')
else:
    print('No Aurora product found')

conn.close()
"

